static inline bool worldMaskLand(int x, int y) {
    if (x < 0 || x >= WORLD_MASK_W || y < 0 || y >= WORLD_MASK_H) return false;
    return (WORLD_MASK[y * WORLD_MASK_ROWBYTES + (x >> 3)] >> (7 - (x & 7))) & 1;
}
